import { IWcBindable, SseConnectOptions, WcsSseMessage } from "../types.js";
import { WcsIoErrorInfo } from "./platformCapability.js";
import { deriveSseErrorInfo, WcsSseErrorKind } from "./sseCapabilities.js";

// EventSource readyState values. Hardcoded rather than read from the global
// EventSource so the Core does not require EventSource to exist at module load
// (happy-dom omits it; tests inject a mock).
const SSE_OPEN = 1;
const SSE_CLOSED = 2;

export class SseCore extends EventTarget {
  static wcBindable: IWcBindable = {
    protocol: "wc-bindable",
    version: 1,
    properties: [
      { name: "message", event: "wcs-sse:message", semantics: "event" },
      { name: "connected", event: "wcs-sse:connected-changed", semantics: "state" },
      { name: "loading", event: "wcs-sse:loading-changed", semantics: "state" },
      { name: "error", event: "wcs-sse:error", semantics: "state" },
      // Serializable failure taxonomy (stable code / phase / recoverable), or null.
      // Additive bindable output derived from `error` via an explicit `kind`
      // discriminator (invalid-argument / connection-error, split by phase +
      // recoverable). The existing `error` property/event are unchanged. Fires
      // wcs-sse:error-info-changed. No lane — SSE is a session/streaming monitor.
      { name: "errorInfo", event: "wcs-sse:error-info-changed", semantics: "state" },
      { name: "readyState", event: "wcs-sse:readystate-changed", semantics: "state" },
    ],
    commands: [
      { name: "connect" },
      { name: "close" },
    ],
  };

  private _target: EventTarget;
  private _es: EventSource | null = null;
  private _message: WcsSseMessage | null = null;
  private _connected: boolean = false;
  private _loading: boolean = false;
  private _error: Event | Error | null = null;
  private _errorInfo: WcsIoErrorInfo | null = null;
  private _readyState: number = SSE_CLOSED;

  private _url: string = "";
  private _withCredentials: boolean = false;
  private _events: string[] = [];
  private _raw: boolean = false;
  // stale-after (ms, 0 = off): the time of the last open / event, and the watchdog's timer
  private _staleAfter: number = 0;
  private _lastActivity: number = 0;
  private _staleTimer: ReturnType<typeof setTimeout> | null = null;

  // auto-reconnect（<wcs-ws> と同じ名前・同じ意味）: ブラウザが諦めたストリーム（恒久エラー、
  // readyState CLOSED）だけを reconnectInterval ms 後に開き直す。ブラウザが自分で再接続する
  // 一過性の切断（CONNECTING）には手を出さない。回数は開き直しの試行ごとに数え、open で 0 に戻る。
  private _autoReconnect: boolean = false;
  private _reconnectInterval: number = 3000;
  private _maxReconnects: number = Infinity;
  private _reconnectCount: number = 0;
  private _reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  // 開き直しの url を試行のときに返す（null: connect() に渡された url）。Shell はそのときの url を渡す。
  private _reconnectUrl: (() => string) | null = null;

  // Generation guard (§3.4): bumped on every _doConnect (new live stream) and on
  // dispose(). The shared arrow-function listeners (_onOpen/_onMessage/_onError)
  // capture the generation of the connection they belong to in _connGen; once
  // dispose() (or a superseding connect()) advances _gen, a still-attached
  // listener from a torn-down stream sees a stale _connGen and writes nothing.
  // A boolean flag is insufficient (dispose→observe would let stale work slip
  // through). Listeners are normally removed on close()/permanent-error, so this
  // guard backstops the dispose() path where teardown and a late native event
  // could otherwise race.
  private _gen = 0;
  private _connGen = 0;
  // SSR (§3.8): SSE has no synchronous probe to await — readiness is immediate.
  // The stream itself is opened on demand via connect(), not at observe() time.
  private _ready: Promise<void> = Promise.resolve();

  constructor(target?: EventTarget) {
    super();
    this._target = target ?? this;
  }

  get ready(): Promise<void> {
    return this._ready;
  }

  // Lifecycle (§3.5). SSE is command-driven: the stream is opened by connect(),
  // not by observe(). observe() is therefore an idempotent no-op that resolves
  // once ready; dispose() invalidates in-flight listeners (_gen++) and tears the
  // stream down via close() — a pending auto-reconnect included.
  observe(): Promise<void> {
    return this._ready;
  }

  dispose(): void {
    this._gen++;
    this._closeInternal();
  }

  get message(): WcsSseMessage | null {
    return this._message;
  }

  get connected(): boolean {
    return this._connected;
  }

  get loading(): boolean {
    return this._loading;
  }

  get error(): Event | Error | null {
    return this._error;
  }

  /**
   * The last failure's serializable `WcsIoErrorInfo` (stable `code` / `phase` /
   * `recoverable`), or null. Additive wc-bindable property (event
   * `wcs-sse:error-info-changed`), derived from `error`; the existing `error`
   * property/event are unchanged. `recoverable=true` only for a transient
   * CONNECTING drop (the browser auto-reconnects).
   */
  get errorInfo(): WcsIoErrorInfo | null {
    return this._errorInfo;
  }

  get readyState(): number {
    return this._readyState;
  }

  // --- State setters with event dispatch ---

  private _setMessage(message: WcsSseMessage): void {
    this._message = message;
    this._target.dispatchEvent(new CustomEvent("wcs-sse:message", {
      detail: message,
      bubbles: true,
    }));
  }

  // connected/loading/error/readyState are idempotent *status* (not events), so
  // they carry a same-value guard: native reconnection re-fires `error` while the
  // stream sits in CONNECTING, and without the guard each retry would re-emit an
  // unchanged connected=false / loading=true / readyState=CONNECTING. `message`
  // is deliberately NOT guarded (a received event is a distinct occurrence each
  // time). `error` uses reference identity — every real failure is a fresh Event,
  // so it still re-fires; only redundant null→null clears are suppressed.

  private _setConnected(connected: boolean): void {
    if (this._connected === connected) return;
    this._connected = connected;
    this._target.dispatchEvent(new CustomEvent("wcs-sse:connected-changed", {
      detail: connected,
      bubbles: true,
    }));
  }

  private _setLoading(loading: boolean): void {
    if (this._loading === loading) return;
    this._loading = loading;
    this._target.dispatchEvent(new CustomEvent("wcs-sse:loading-changed", {
      detail: loading,
      bubbles: true,
    }));
  }

  // `kind` is an explicit discriminator (passed only from the non-null call
  // sites) that classifies the failure into the errorInfo taxonomy without
  // reverse-engineering the mixed `Event | Error` shape — raw EventSource error
  // Events cannot be told apart from a fatal (CLOSED) vs transient (CONNECTING)
  // drop, so the caller supplies it. The clear path (`_setError(null)`) passes no
  // kind; errorInfo is cleared to null in lockstep.
  private _setError(error: Event | Error | null, kind?: WcsSseErrorKind): void {
    if (this._error === error) return;
    this._error = error;
    // Keep the additive `errorInfo` taxonomy in sync with `error`: derive from the
    // kind discriminator (or null on clear). Fires before the `error` event so an
    // observer binding both sees the classification first, mirroring the io-node
    // family. Non-null errors always carry a kind (kind! is a type assertion, not
    // a runtime branch).
    this._commitErrorInfo(error === null ? null : deriveSseErrorInfo(kind!, this._errorMessage(error)));
    this._target.dispatchEvent(new CustomEvent("wcs-sse:error", {
      detail: error,
      bubbles: true,
    }));
  }

  // Called only from _setError (which already same-value-guards on the error
  // reference), so errorInfo transitions exactly when error does — no separate
  // guard needed here.
  private _commitErrorInfo(info: WcsIoErrorInfo | null): void {
    this._errorInfo = info;
    this._target.dispatchEvent(new CustomEvent("wcs-sse:error-info-changed", {
      detail: info,
      bubbles: true,
    }));
  }

  // Extract a message for the errorInfo taxonomy. EventSource `error` Events carry
  // no message field, so they fall back to a stable literal; validation and
  // construction failures are Error/DOMException-like and expose `.message`.
  private _errorMessage(error: Event | Error): string {
    if (error instanceof Event) return "SSE connection error";
    return error.message;
  }

  private _setReadyState(readyState: number): void {
    if (this._readyState === readyState) return;
    this._readyState = readyState;
    this._target.dispatchEvent(new CustomEvent("wcs-sse:readystate-changed", {
      detail: readyState,
      bubbles: true,
    }));
  }

  // --- Public API ---

  /**
   * Open an SSE connection. Required `url`; `options` are evaluated once at the
   * time the EventSource is created.
   *
   * Idempotency / headless note: if already connected (CONNECTING/OPEN) to the
   * *same* url, a re-`connect()` is a no-op — including when `options`
   * (events/raw/withCredentials) differ. The guard keys on url only (see the
   * inline comment below), so to apply new options to a live stream a headless
   * caller must `close()` first, then `connect()` with the new options. After a
   * permanent failure (readyState CLOSED) the guard is bypassed and `connect()`
   * reconnects with the supplied options — a pending auto-reconnect is dropped and
   * its count starts again.
   */
  connect(url: string, options: SseConnectOptions = {}): void {
    // never-throw (§3.6): 引数バリデーション失敗は例外でなく error プロパティに流し、
    // no-op で戻る。command-token 経路からの呼び出しが例外で更新サイクルを壊さず、
    // 「公開メソッドは throw しない」契約に揃える。
    if (!url) {
      this._setError(new Error("url is required."), "invalid-argument");
      return;
    }

    // 同一 url で接続中(CONNECTING/OPEN)なら no-op。同じストリームへの再接続は churn
    // でしかなく（EventSource は再接続をネイティブに行う）、custom element の *upgrade*
    // 経路を吸収する：autoloader がマークアップ存在後にタグを定義すると、仕様により
    // 接続済み要素で attributeChangedCallback(isConnected===true) と connectedCallback
    // が両方発火し Shell が connect() を2回呼ぶ。このガードが無いと接続を1本開いて即破棄
    // する。CLOSED（恒久エラー後）は guard を外れて再接続できる。
    // ※ events/raw/withCredentials は observedAttributes 外で宣言的には変更できないため
    //   url 一致のみで判定する（broadcast の open() が name 一致で冪等化するのと同型）。
    if (this._es && this._url === url && this._readyState !== SSE_CLOSED) {
      return;
    }

    // 既存の接続をクローズ
    this._closeInternal();

    this._url = url;
    this._withCredentials = options.withCredentials ?? false;
    this._events = options.events ?? [];
    this._raw = options.raw ?? false;
    this._staleAfter = options.staleAfter !== undefined && options.staleAfter > 0 ? options.staleAfter : 0;
    this._autoReconnect = options.autoReconnect ?? false;
    this._reconnectInterval = options.reconnectInterval ?? 3000;
    this._maxReconnects = options.maxReconnects ?? Infinity;
    this._reconnectUrl = options.reconnectUrl ?? null;
    this._reconnectCount = 0;

    this._doConnect();
  }

  close(): void {
    this._closeInternal();
  }

  /**
   * Closes like close() — `connected` / `loading` / `readyState` are published at once — and says
   * whether a stream was open, opening or about to reopen (auto-reconnect). The Shell uses it when
   * the page unloads or may enter the back/forward cache, and opens the stream again when the
   * document stays or comes back (<wcs-ws>'s core has the same method).
   */
  suspend(): boolean {
    const live = this._es !== null || this._reconnectTimer !== null;
    this._closeInternal();
    return live;
  }

  // --- Internal ---

  private _doConnect(): void {
    // 状態通知（_setLoading/_setError）は同期 dispatch するため、リスナが再入的に
    // connect(別url)/close() を呼ぶと this._es を差し替え得る。_onError と同じ所有権
    // ガードを敷くため、(1) EventSource 生成・リスナ登録を *先に* 済ませて this._es を
    // 確定させ、(2) 確定後に状態通知を出す、という順序にする。通知 dispatch で再入が
    // 起きても、その時点で外側は自分の es を確定済みなので「dispatch 後に this._es を
    // 上書きする」逸脱が起きない。
    let es: EventSource;
    try {
      es = this._withCredentials
        ? new EventSource(this._url, { withCredentials: true })
        : new EventSource(this._url);
    } catch (e) {
      // 生成失敗：dispatch はまだしていないので this._es 上書き競合は無い。
      this._es = null;
      this._setLoading(false);
      // stream 未確立の構築失敗 → connection-error / start / recoverable=false
      // (EventSource が無いためブラウザの自動再接続は起きない)。
      this._setError(e as Error, "connection-start");
      return;
    }

    this._es = es;
    // この接続の世代を確定（§3.4）。以降この es のリスナはこの世代に属する。dispose()
    // で _gen が進むとこの es のリスナは stale 判定になり状態を書かなくなる。
    this._connGen = ++this._gen;
    // この時点の events を捕捉（再入で this._events が差し替わってもこの es の解除に使う）。
    const events = this._events;

    es.addEventListener("open", this._onOpen);
    es.addEventListener("message", this._onMessage);
    es.addEventListener("error", this._onError);
    // 名前付きイベント（`event:` フィールド）を購読し、すべて message に集約する。
    // SSE 仕様上、名前付きイベントも message と同じく MessageEvent として配送される
    // （data/lastEventId を持つ）ため _onMessage(event: MessageEvent) で受けて問題ない。
    // addEventListener のシグネチャ上 EventListener へのキャストが要るだけで実害はない。
    for (const name of events) {
      es.addEventListener(name, this._onMessage as EventListener);
    }

    // ここから状態通知。各 dispatch のリスナが再入して this._es を差し替えたら、以降の
    // 通知を放棄し、自分が生成した es をリスナごと破棄する（リーク防止＋再入側の状態を
    // 上書きしない。_onError の `if (this._es !== es) return;` と同型の所有権ガード）。
    this._setLoading(true);
    if (this._es !== es) { this._removeListeners(es, events); es.close(); return; }
    this._setError(null);
    if (this._es !== es) { this._removeListeners(es, events); es.close(); return; }
    this._setReadyState(es.readyState);
  }

  private _onOpen = (): void => {
    // §3.4: dispose() で世代が進んだ後に届いた stale イベントは無視する（torn-down
    // 要素への書き込み防止）。
    if (this._connGen !== this._gen) return;
    // 開いた: auto-reconnect の回数は数え直す（<wcs-ws> と同じ）
    this._reconnectCount = 0;
    this._lastActivity = Date.now();
    this._armStale();
    this._setLoading(false);
    this._setConnected(true);
    this._setReadyState(SSE_OPEN);
    // 接続確立時に error をクリアする。ネイティブ再接続（トランジェントエラー後）は
    // _doConnect を経由せず open が直接発火するため、ここでクリアしないと
    // connected=true のまま古い error Event が残り state に不整合が露出する。
    // same-value ガードにより、error が元々 null なら冗長な dispatch は起きない。
    this._setError(null);
  };

  private _onMessage = (event: MessageEvent): void => {
    // §3.4: dispose() 後に届いた stale メッセージは破棄する。
    if (this._connGen !== this._gen) return;
    this._lastActivity = Date.now();
    let data: any = event.data;
    // JSONの自動パース（raw 指定時はテキストのまま）
    if (!this._raw && typeof data === "string") {
      try {
        data = JSON.parse(data);
      } catch {
        // テキストのまま
      }
    }
    this._setMessage({
      event: event.type,
      data,
      // WcsSseMessage.lastEventId は非 null string 契約。実 MessageEvent では常に
      // string（無指定時は ""）だが、named-event 購読の `as EventListener` キャストで
      // 型保証を握り潰しているため、念のため ?? "" でフォールバックし契約を守る。
      lastEventId: event.lastEventId ?? "",
    });
  };

  private _onError = (event: Event): void => {
    // §3.4: dispose() 後に届いた stale エラーは破棄する。
    if (this._connGen !== this._gen) return;
    // 発火元の EventSource をローカル退避してから dispatch する。_setError は
    // wcs-sse:error を同期 dispatch するため、リスナが再入的に close()/connect() を
    // 呼ぶと _closeInternal が this._es を null（または新インスタンス）に差し替え得る。
    // 退避しないと dispatch 後の readyState 参照が null 参照でクラッシュし、再入が
    // 確定させた状態を後続の setter が上書き・巻き戻す不整合も生む。
    const es = this._es!;
    const state = es.readyState;

    // errorInfo の分類は先読みした state で決める。CLOSED＝恒久エラー
    // (connection-fatal / recoverable=false)、それ以外(CONNECTING)＝ブラウザが
    // 自動再接続中(connection-transient / recoverable=true)。this._setReadyState
    // より前に確定させるのは、_setError が同期 dispatch する error-info-changed が
    // 正しい recoverable を載せて流れるようにするため。
    this._setError(event, state === SSE_CLOSED ? "connection-fatal" : "connection-transient");

    // 再入した close()/connect() で自分が無効化されたら、以降の状態更新は放棄する
    // （再入側が確定させた状態が正。broadcast の _onMessage が dispatch 後に
    // ライフサイクル参照を deref しないのと同等の堅牢性に揃える）。
    if (this._es !== es) return;

    // EventSource は CloseEvent を持たず、error が切断も兼ねる。
    // readyState で「再接続中(CONNECTING)」と「死亡(CLOSED)」を判別する。
    // 以下の setter も同期 dispatch する。そのリスナが close()/connect() を呼んだら、同じく
    // 以降を放棄する: 再入側の _closeInternal が片付け済みで、続けると再入した接続の状態を
    // 巻き戻し（loading など）、死んだ es と取り違えて新しい es の参照を捨て、close() の後に
    // auto-reconnect を予約してしまう。
    this._setReadyState(state);
    if (this._es !== es) return;
    this._setConnected(false);
    if (this._es !== es) return;
    // CLOSED ＝ ネイティブ再接続は行われない（恒久エラー）。
    // それ以外（CONNECTING）＝ ブラウザが自動再接続中なので loading を維持。
    this._setLoading(state !== SSE_CLOSED);
    if (this._es !== es) return;

    // 恒久エラー時は死んだ EventSource をリスナごと即時破棄する。次の connect()/close()
    // まで放置すると死んだインスタンスとリスナを保持し続けるため。状態は上で CLOSED に
    // 揃え済みなので _closeInternal は使わず（再 dispatch 不要）、参照だけ解放する。
    if (state === SSE_CLOSED) {
      // ここでは所有権ガードを通過済みのため this._es === es。
      this._removeListeners(es, this._events);
      this._es = null;
      // 見張るものは次の open まで無い
      this._clearStaleTimer();
      // ブラウザが諦めたストリーム: auto-reconnect なら開き直しを予約する。回数が尽きたら
      // 予約せず、最後の error が残る（<wcs-ws> と同じ）。
      if (this._autoReconnect && this._reconnectCount < this._maxReconnects) {
        this._scheduleReconnect();
      }
    }
  };

  // 開き直しは reconnectInterval ms 後に 1 本だけ。試行のときの url で開く（Shell はそのときの
  // 要素の url を渡す — state の getter が url を作るなら、更新したトークンはもう入っている）。
  // url が空の試行は何もしない（数えず、次も予約しない）。connect()/close()/dispose() が
  // _closeInternal でタイマーを外す。世代の確認はその裏打ち。
  private _scheduleReconnect(): void {
    const gen = this._gen;
    this._clearReconnectTimer();
    this._reconnectTimer = setTimeout(() => {
      this._reconnectTimer = null;
      if (gen !== this._gen) return;
      const url = this._reconnectUrl !== null ? this._reconnectUrl() : this._url;
      if (!url) return;
      this._reconnectCount++;
      this._url = url;
      this._doConnect();
    }, this._reconnectInterval);
  }

  private _clearReconnectTimer(): void {
    if (this._reconnectTimer !== null) {
      clearTimeout(this._reconnectTimer);
      this._reconnectTimer = null;
    }
  }

  // 特定の EventSource とその登録時の events からリスナを解除する。再入で this._es や
  // this._events が差し替わった後でも、捕捉済みの es/events を渡せば正しく解除できる。
  // 呼び出し側が常に非 null の es を渡す（_closeInternal は `if (this._es)` 内、
  // _doConnect は生成直後の es を渡す）ため null ガードは置かない。
  private _removeListeners(es: EventSource, events: string[]): void {
    es.removeEventListener("open", this._onOpen);
    es.removeEventListener("message", this._onMessage);
    es.removeEventListener("error", this._onError);
    for (const name of events) {
      es.removeEventListener(name, this._onMessage as EventListener);
    }
  }

  // stale-after の見張り。開いている間、最後の open / イベントから staleAfter ms 何も届かなければ、
  // 接続は失われたとみなして開き直す（docs/seam-apps.md、shift-desk: 閉じられずに死んだ接続 —
  // スリープ・NAT・proxy — に EventSource は気づかず OPEN のまま、ページは "Live" と言い続けた）。
  // タイマーは 1 本だけ持ち、満了のたびに最後の活動からの残りで張り直す（イベントごとに張り直さない）。
  private _armStale(): void {
    if (this._staleAfter === 0 || this._staleTimer !== null) return;
    this._staleTimer = setTimeout(this._checkStale, this._staleAfter);
  }

  private _checkStale = (): void => {
    this._staleTimer = null;
    // 開いていない（ネイティブの再接続中・閉じた）間は見張らない — 次の open が張り直す
    if (this._es === null || this._readyState !== SSE_OPEN) return;
    const idle = Date.now() - this._lastActivity;
    if (idle < this._staleAfter) {
      this._staleTimer = setTimeout(this._checkStale, this._staleAfter - idle);
      return;
    }
    // 失われたとみなす: 閉じて（connected / readyState を知らせる）同じ url で開き直し、理由を
    // error に残す（回復できるもの。次の open が消す）。位置は url（`since=`）か、サーバーが最初に
    // 送る `id:` で伝える — 新しい EventSource は Last-Event-ID を送らない。
    const lost = new Error(`No event for ${this._staleAfter} ms: the stream is treated as lost and reopened.`);
    this._closeInternal();
    this._doConnect();
    if (this._es !== null) this._setError(lost, "connection-transient");
  };

  private _clearStaleTimer(): void {
    if (this._staleTimer !== null) {
      clearTimeout(this._staleTimer);
      this._staleTimer = null;
    }
  }

  private _closeInternal(): void {
    this._clearStaleTimer();
    this._clearReconnectTimer();
    if (this._es) {
      this._removeListeners(this._es, this._events);
      this._es.close();
      this._es = null;
    }
    // EventSource.close() はイベントを発火しないため状態を手動でリセット。
    // 各 setter が same-value ガードを持つので、冗長な dispatch は起きない。
    this._setConnected(false);
    this._setLoading(false);
    this._setReadyState(SSE_CLOSED);
  }
}
